function validate([nums1, nums2]) {
  if (nums1.length < 3 || nums1.length > 200) return 'nums1 needs 3 to 200 values.';
  if (nums2.length !== nums1.length - 2) return 'nums2 must have exactly two values fewer than nums1.';
  if ([...nums1, ...nums2].some(v => v < 0 || v > 1000)) return 'Every value is from 0 to 1000.';
  // The smallest kept value is one of the three smallest of nums1, so only three shifts can work.
  const a = [...nums1].sort((p, q) => p - q), b = [...nums2].sort((p, q) => p - q);
  const works = x => { let k = 0; for (const v of a) if (k < b.length && v + x === b[k]) k++; return k === b.length; };
  if (![0, 1, 2].some(i => works(b[0] - a[i]))) return 'nums2 must come from nums1 by deleting two values and adding one x to the rest.';
  return null;
}

