    const x = nums2[0] - nums1[first];
    let matched = 0;
    for (let i = 0; i < nums1.length && matched < nums2.length; i++) {
      if (nums1[i] + x === nums2[matched]) {
        matched++;
      }
    }
    if (matched === nums2.length) {
      return x;
    }
  }
  return nums2[0] - nums1[0];
}

