function minimumAddedInteger(nums1, nums2) {
  // Delete every pair of positions, read x off the sums, and compare the sorted results.
  const want = [...nums2].sort((a, b) => a - b).join();
  const total2 = nums2.reduce((s, v) => s + v, 0);
  let best = Infinity;
  for (let i = 0; i < nums1.length; i++) {
    for (let j = i + 1; j < nums1.length; j++) {
      const rest = nums1.filter((_, k) => k !== i && k !== j);
      const diff = total2 - rest.reduce((s, v) => s + v, 0);
      if (diff % rest.length !== 0) continue;
      const x = diff / rest.length;
      if (rest.map(v => v + x).sort((a, b) => a - b).join() === want) best = Math.min(best, x);
    }
  }
  return best;
}

