function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 200 : pick(3, 9);
  // A narrow value range gives duplicates and several valid shifts.
  const top = large ? 1000 : pick(1, 12);
  const nums1 = Array.from({ length: n }, () => pick(0, top));
  const i = pick(0, n - 1);
  let j = pick(0, n - 2);
  if (j >= i) j++;
  const rest = nums1.filter((_, k) => k !== i && k !== j);
  const low = Math.min(...rest), high = Math.max(...rest);
  const reach = large ? 1000 : 10;
  const x = pick(Math.max(-low, -reach), Math.min(1000 - high, reach));
  const nums2 = rest.map(v => v + x);
  for (let k = nums2.length - 1; k > 0; k--) {
    const r = pick(0, k);
    [nums2[k], nums2[r]] = [nums2[r], nums2[k]];
  }
  return [nums1, nums2];
}
